import {COURSE} from './core.mjs';
import {proofIsCurrent} from './operations.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function connectionCards(cases,backend,cfg={}){
 const latest=(predicate)=>cases.filter(predicate).sort((a,b)=>Date.parse(b.sources?.payment?.checkedAt||b.createdAt)-Date.parse(a.sources?.payment?.checkedAt||a.createdAt))[0];
 const payment=latest(s=>s.capture?.source==='paypal-sandbox'&&s.sources?.payment),access=latest(s=>s.sources?.access);
 const cards=[
 ['PayPal sandbox',!backend?'Simulated':payment?.sources.payment.status==='unavailable'?'Check failed':payment?'Evidence checked':cfg.paypal?'Configured · not checked':'Not configured','Payment must match the exact purchase. A successful case read does not check every transaction.','Set PAYPAL_CLIENT_ID and PAYPAL_CLIENT_SECRET in Render. Complete sandbox checkout, then refresh that case.',payment?.sources.payment.lastSuccessAt],
 ['Course access',!backend?'Simulated':access?.sources.access.status==='unavailable'?'Check failed':access?'Demo service checked':'Demo service ready','Uses our controlled course service. No external course platform is connected.','Open a case to inspect its entitlement. Verify the protected lesson after an approved correction.',access?.sources.access.lastSuccessAt],
 ['AI specialists',!backend||!cfg.ai?'Scripted demonstration':cases.some(s=>s.review&&s.review.mode!=='scripted')?'Model review recorded':'Configured · not checked','Evidence references support inspection; they are not a guarantee of accuracy.','Set OPENAI_API_KEY and OPENAI_MODEL on the server. Unlock the operator session and investigate a case.',null],
 ['Render Workflows',!backend||!cfg.workflows?'Not configured':cases.some(s=>s.job?.error)?'Run needs attention':cases.some(s=>s.job?.pending)?'Run in progress':cases.some(s=>s.job?.runId)?'Run recorded':'Configured · not checked','Investigation and approved recovery are separate runs. A recorded run is not a connection health check.','Deploy workflows, configure the task identifiers and shared secret, then inspect both runs in Render.',null]
 ];
 return `<div class="connection-banner"><strong>Setup → evidence → verified outcome</strong><p>Statuses reflect configuration and records in this workspace. Secrets stay in your server environment.</p></div><div class="connection-grid">${cards.map(([name,status,copy,setup,at],i)=>`<section class="surface connection-card"><span class="eyebrow">0${i+1} / CONNECTION</span><h2>${name}</h2><span class="badge neutral">${esc(status)}</span><p>${copy}</p>${at?`<small>Last successful source read: ${esc(new Date(at).toLocaleString())}</small>`:''}<details><summary>Setup and next check</summary><p>${setup}</p></details></section>`).join('')}</div><section class="setup-note"><h2>Complete one purchase from start to finish.</h2><p>Start with a sandbox case, confirm payment, review the evidence, approve the correction, then verify the lesson.</p><a class="button" href="recover.html">Open checkout & operator setup</a> <a class="button" href="https://github.com/sagitta414/paytrace-recover/blob/main/docs/BUILD-README.md" target="_blank" rel="noopener">Deployment guide ↗</a></section>`;
}
export function caseExperience(s,{uncertain=false,backend=false}={}){
 const verified=proofIsCurrent(s)&&!uncertain,stages=[['Payment',s.capture?.status==='COMPLETED'],['Access checked',s.sources?.access?.status==='available'],['Review',!!s.review],['Approval',!!s.approval],['Verification',verified]];
 return `${uncertain?'<section class="approval-brief" role="status"><h3>Let’s confirm what happened.</h3><p>A failed request does not prove an access change failed. Refresh the records before deciding what to do next.</p><button class="button" data-action="refresh">Check current status</button></section>':''}<section class="case-progress" aria-label="Recovery checkpoints"><div class="section-head"><h3>From payment to access</h3><span class="subtle">${s.job?.pending?'Workflow running':uncertain?'Refresh required':'Current case'}</span></div><ol>${stages.map(([label,done])=>`<li class="${done&&!uncertain?'checked':''}"><span>${done&&!uncertain?'✓':'○'}</span>${label}</li>`).join('')}</ol>${s.job?.runId?`<p class="footnote">Workflow reference: ${esc(s.job.runId)}</p>`:''}${s.job?.error?`<p role="status">Workflow needs attention. Refresh status before another action.</p>`:''}</section>
 ${s.rehearsal?`<section class="approval-brief"><span class="eyebrow">${s.writes?'APPROVED CHANGE':'YOUR DECISION'}</span><h3>One course. One customer. One access grant.</h3><dl><div><dt>Customer</dt><dd>${esc(s.customerName)}</dd></div><div><dt>Purchased course</dt><dd>${esc(COURSE.name)}</dd></div><div><dt>Correction</dt><dd>Activate this purchase’s course entitlement</dd></div><div><dt>Payment</dt><dd>Existing capture · no additional charge or refund</dd></div></dl><p>${s.approval?'Approval recorded for this evidence version.':'Approval applies to the previewed evidence. Changes require a new review.'}</p></section>`:''}
 <section class="learner-preview"><div><span class="eyebrow">CUSTOMER VIEW / DEMO COURSE</span><h3>${verified?'The lesson is ready.':s.entitlement.active?'Access updated. Proof still matters.':'What the customer is waiting for.'}</h3><p>${esc(COURSE.name)}</p></div><div class="lesson-tile"><span>${s.entitlement.active?'ACCESS RECORD ACTIVE':'COURSE LOCKED'}</span><strong>01 / See the light</strong><p>${verified?'The independent check retrieved this lesson for the purchased entitlement.':uncertain?'Current access is unconfirmed. Refresh the case before continuing.':'The customer’s lesson becomes available only when the correct entitlement is active.'}</p><button class="button" data-lesson-preview ${!s.entitlement.active||uncertain?'disabled':''}>${backend?'Check & open demo lesson':'Preview simulated lesson'}</button><div class="lesson-result" role="status"></div></div></section>
 ${s.proof?`<section class="verification-receipt ${verified?'passed':''}"><span class="eyebrow">${verified?'VERIFIED OUTCOME':'VERIFICATION INCOMPLETE'}</span><h3>${verified?'A receipt for the outcome.':'Keep this case open.'}</h3><p>${esc(s.customerName)} · ${esc(COURSE.name)}</p><ul>${s.proof.checks.map(c=>`<li>${c.ok?'✓':'!'} ${esc(c.label)}</li>`).join('')}</ul><p>Checked ${esc(new Date(s.proof.at).toLocaleString())}</p><p class="footnote">${esc(s.proof.transport)} · ${s.writes} access grant(s) · ${s.reads} verification attempt(s). ${uncertain?'This result is not currently confirmed.':''}</p><button class="button" data-action="receipt">Download case receipt</button></section>`:''}`;
}
export function mountExperience(root,s,{backend,uncertain,api}){
 if(!s)return;const body=root.querySelector('.sheet-body');if(!body)return;
 const panel=document.createElement('div');panel.className='case-experience';panel.innerHTML=caseExperience(s,{backend,uncertain});body.append(panel);
 const button=panel.querySelector('[data-lesson-preview]'),result=panel.querySelector('.lesson-result');
 button.onclick=async()=>{button.disabled=true;result.textContent='Checking the selected learner’s access…';try{if(backend){const lesson=await api('lesson');if(!lesson.accessible||lesson.userId!==s.order.userId||lesson.courseId!==s.order.courseId)throw Error('The selected case changed. Reopen this case before viewing the lesson.');result.textContent=lesson.title+' '+lesson.body;}else result.textContent='Simulated lesson preview: Find soft window light and make three frames. This did not retrieve protected content from a server.';}catch(e){result.textContent='Lesson could not be confirmed. '+e.message;}finally{button.disabled=false;}};
}
